import { useEffect, useMemo, useState } from "react";
import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle } from "@/shared/ui/dialog";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/shared/ui/tabs";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/shared/ui/card";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/shared/ui/table";
import { Badge } from "@/shared/ui/badge";
import { supabase } from "@/integrations/supabase/client";
import { format } from "date-fns";
import { ptBR } from "date-fns/locale";
import { TrendingUp } from "lucide-react";

interface WorkReportsModalProps {
  isOpen: boolean;
  onClose: () => void;
  storesMap?: Record<number, string>;
}

interface WorkEntry {
  id: string;
  tipo: 'perfil' | 'avulso';
  nome: string;
  work_date: string;
  valor_diaria: number;
  loja_id: number | null;
  local_tipo: string | null;
  evento_nome: string | null;
  setor: string | null;
  observacao: string | null;
}

export function WorkReportsModal({ isOpen, onClose, storesMap = {} }: WorkReportsModalProps) {
  const [rows, setRows] = useState<WorkEntry[]>([]);
  const [loading, setLoading] = useState(false);

  const parseDateLocal = (s: string): Date => {
    if (!s) return new Date(NaN);
    const parts = s.split('-');
    const y = Number(parts[0]);
    const m = Number(parts[1]);
    const dPart = parts[2] || '01';
    const d = Number(dPart.slice(0, 2));
    return new Date(y, m - 1, d);
  };

  useEffect(() => {
    const load = async () => {
      if (!isOpen) return;
      setLoading(true);
      try {
        const { data: fwRows, error: fwError } = await supabase
          .from('freelancer_work_days')
          .select('id, freelancer_id, work_date, valor_diaria, loja_id, local_tipo, evento_nome, setor, observacao');
        if (fwError) throw fwError;
        const fw = fwRows || [];

        const freelancerIds = Array.from(new Set(fw.map((r: any) => r.freelancer_id).filter(Boolean)));
        let nameMap: Record<string, string> = {};
        if (freelancerIds.length > 0) {
          const { data: fRows, error: fErr } = await supabase
            .from('freelancers')
            .select('id, nome')
            .in('id', freelancerIds);
          if (fErr) throw fErr;
          nameMap = Object.fromEntries((fRows || []).map((f: any) => [f.id, f.nome]));
        }

        const perfilEntries: WorkEntry[] = fw.map((r: any) => ({
          id: r.id,
          tipo: 'perfil',
          nome: nameMap[r.freelancer_id] || '—',
          work_date: r.work_date,
          valor_diaria: Number(r.valor_diaria || 0),
          loja_id: r.loja_id ?? null,
          local_tipo: r.local_tipo ?? null,
          evento_nome: r.evento_nome ?? null,
          setor: r.setor ?? null,
          observacao: r.observacao ?? null,
        }));

        const { data: avRows, error: avErr } = await supabase
          .from('freelancer_avulso_work_days')
          .select('id, nome, work_date, valor_diaria, loja_id, local_tipo, evento_nome, setor, observacao');
        if (avErr) throw avErr;
        const avulsoEntries: WorkEntry[] = (avRows || []).map((r: any) => ({
          id: r.id,
          tipo: 'avulso',
          nome: r.nome,
          work_date: r.work_date,
          valor_diaria: Number(r.valor_diaria || 0),
          loja_id: r.loja_id ?? null,
          local_tipo: r.local_tipo ?? null,
          evento_nome: r.evento_nome ?? null,
          setor: r.setor ?? null,
          observacao: r.observacao ?? null,
        }));

        const all = [...perfilEntries, ...avulsoEntries].sort(
          (a, b) => parseDateLocal(a.work_date).getTime() - parseDateLocal(b.work_date).getTime()
        );
        setRows(all);
      } catch (err) {
        console.error('[WorkReportsModal] Erro ao buscar trabalhos:', err);
      } finally {
        setLoading(false);
      }
    };
    load();
  }, [isOpen]);

  const total = useMemo(() => rows.reduce((s, r) => s + (r.valor_diaria || 0), 0), [rows]);

  return (
    <Dialog open={isOpen} onOpenChange={onClose}>
      <DialogContent className="w-full h-full max-w-none max-h-none m-0 p-0 rounded-none sm:max-w-6xl sm:max-h-[90vh] sm:m-6 sm:rounded-lg">
        <DialogHeader className="sticky top-0 z-10 bg-background border-b p-4 flex flex-row items-center justify-between space-y-0">
          <div className="flex items-center gap-2">
            <TrendingUp className="h-5 w-5" />
            <DialogTitle className="text-lg font-semibold">Relatórios de Trabalhos</DialogTitle>
          </div>
          <DialogDescription className="sr-only">
            Lista geral de trabalhos registrados
          </DialogDescription>
        </DialogHeader>

        <div className="flex-1 overflow-hidden">
          <Tabs defaultValue="lista" className="h-full flex flex-col">
            <TabsList className="grid w-full grid-cols-1 h-12 mx-4 mt-4 mb-2">
              <TabsTrigger value="lista" className="text-sm font-medium h-10">Lista</TabsTrigger>
            </TabsList>

            <TabsContent value="lista" className="flex-1 overflow-hidden p-4">
              <Card className="h-full flex flex-col">
                <CardHeader className="pb-4">
                  <div className="flex items-center justify-between">
                    <div>
                      <CardTitle className="flex items-center gap-2 text-lg">Trabalhos Registrados</CardTitle>
                      <CardDescription className="text-sm">Conferência dos trabalhos (perfil e avulso)</CardDescription>
                    </div>
                    <div className="text-right">
                      <span className="text-sm text-muted-foreground">Total</span>
                      <div className="text-lg font-semibold">R$ {total.toFixed(2)}</div>
                    </div>
                  </div>
                </CardHeader>
                <CardContent className="flex-1 overflow-auto">
                  {loading ? (
                    <div className="flex items-center justify-center h-48 text-muted-foreground">Carregando...</div>
                  ) : rows.length > 0 ? (
                    <div className="overflow-x-auto">
                      <Table>
                        <TableHeader>
                          <TableRow>
                            <TableHead>Data</TableHead>
                            <TableHead>Nome</TableHead>
                            <TableHead>Origem</TableHead>
                            <TableHead>Loja</TableHead>
                            <TableHead>Local</TableHead>
                            <TableHead>Evento</TableHead>
                            <TableHead>Setor</TableHead>
                            <TableHead className="text-right">Valor (R$)</TableHead>
                            <TableHead>Observação</TableHead>
                          </TableRow>
                        </TableHeader>
                        <TableBody>
                          {rows.map((r) => (
                            <TableRow key={`${r.tipo}-${r.id}`}>
                              <TableCell>{format(parseDateLocal(r.work_date), 'dd/MM/yyyy', { locale: ptBR })}</TableCell>
                              <TableCell className="whitespace-nowrap">{r.nome}</TableCell>
                              <TableCell>
                                <Badge variant="outline" className="text-xs">
                                  {r.tipo === 'perfil' ? 'Perfil' : 'Avulso'}
                                </Badge>
                              </TableCell>
                              <TableCell>{r.loja_id != null ? (storesMap[r.loja_id] || '-') : '-'}</TableCell>
                              <TableCell>{r.local_tipo || '-'}</TableCell>
                              <TableCell className="max-w-48 truncate" title={r.evento_nome || ''}>{r.evento_nome || '-'}</TableCell>
                              <TableCell>{r.setor || '-'}</TableCell>
                              <TableCell className="text-right font-medium">R$ {Number(r.valor_diaria || 0).toFixed(2)}</TableCell>
                              <TableCell className="max-w-64 truncate" title={r.observacao || ''}>{r.observacao || '-'}</TableCell>
                            </TableRow>
                          ))}
                        </TableBody>
                      </Table>
                    </div>
                  ) : (
                    <div className="text-center py-10 text-muted-foreground">Nenhum trabalho encontrado</div>
                  )}
                </CardContent>
              </Card>
            </TabsContent>
          </Tabs>
        </div>
      </DialogContent>
    </Dialog>
  );
}

