/**
 * Dashboard Executivo de RH/DP — Master/Admin only.
 *
 * 5 seções estratégicas: Visão (north-star KPIs), Movimentação, Composição,
 * Clima & Engajamento, Compliance & Disciplina. Filtros globais sticky e
 * navegação por âncoras.
 *
 * Frameworks: People Analytics (Visier/Gartner), OKRs HR (BCG), SHRM.
 */

import { useEffect, useMemo, useRef, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { ArrowLeft, LineChart, Loader2 } from 'lucide-react';
import { Button } from '@/shared/ui/button';
import { MommaPageLayout } from '@/shared/ui/MommaPageLayout';
import { TelemetryErrorBoundary } from '@/shared/ui/TelemetryErrorBoundary';
import { useAnalyticsData, type AnalyticsFilters } from '../model/useAnalyticsData';
import { usePermissions } from '@/shared/hooks/usePermissions';
import { FilterBar, SECTIONS } from './analytics/FilterBar';
import { HeroKpis } from './analytics/HeroKpis';
import { MovimentacaoSection } from './analytics/MovimentacaoSection';
import { ComposicaoSection } from './analytics/ComposicaoSection';
import { ClimaSection } from './analytics/ClimaSection';
import { ComplianceSection } from './analytics/ComplianceSection';

export default function AnalyticsPage() {
  return (
    <TelemetryErrorBoundary moduleName="funcionarios-analytics">
      <AnalyticsPageInner />
    </TelemetryErrorBoundary>
  );
}

function AnalyticsPageInner() {
  const navigate = useNavigate();
  const { isAdmin } = usePermissions();
  const isSystemAdmin = isAdmin();
  const [filters, setFilters] = useState<AnalyticsFilters>({
    periodoDias: 90,
