];

const STATUS_PILLS: Record<EmployeeStatus, string> = {
  onboarding: 'bg-blue-500/10 text-blue-700 dark:text-blue-300 border-blue-500/20',
  probation: 'bg-amber-500/10 text-amber-700 dark:text-amber-300 border-amber-500/20',
