  terminated: 'bg-zinc-500/10 text-zinc-600 dark:text-zinc-400 border-zinc-500/20',
  pendente_desligamento: 'bg-red-500/10 text-red-700 dark:text-red-300 border-red-500/30',
};

const PROBATION_PILLS: Record<ReturnType<typeof probationAlertLevel>, string> = {
  safe: 'bg-blue-500/10 text-blue-700 dark:text-blue-300 border-blue-500/20',
